                  if (f_can_id <= 1086) begin
                    if (f_d1 <= 2) begin
                      if (f_d4 <= 165) begin
                        tree4_c = 3'd2;
                      end else begin
                        tree4_c = 3'd0;
                      end
                    end else begin
                      tree4_c = 3'd2;
                    end
                  end else begin
                    if (f_d2 <= 96) begin
                      if (f_can_id <= 1125) begin
                        tree4_c = 3'd0;
                      end else begin
                        if (f_d4 <= 252) begin
                          tree4_c = 3'd2;
                        end else begin
                          tree4_c = 3'd0;
                        end
                      end
                    end else begin
                      tree4_c = 3'd2;
                    end
                  end
                end
              end
            end
          end else begin
            if (f_d3 <= 254) begin
              if (f_d4 <= 0) begin
                if (f_can_id <= 1194) begin
                  tree4_c = 3'd2;
                end else begin
                  if (f_d3 <= 165) begin
                    if (f_can_id <= 1360) begin
                      if (f_d3 <= 150) begin
                        tree4_c = 3'd0;
                      end else begin
                        if (f_can_id <= 1207) begin
                          tree4_c = 3'd0;
                        end else begin
                          tree4_c = 3'd2;
                        end
                      end
                    end else begin
                      tree4_c = 3'd2;
                    end
                  end else begin
                    if (f_d0 <= 103) begin
                      if (f_d3 <= 244) begin
                        if (f_d1 <= 51) begin
                          tree4_c = 3'd2;
                        end else begin
                          tree4_c = 3'd0;
                        end
                      end else begin
                        if (f_d2 <= 235) begin
                          tree4_c = 3'd0;
                        end else begin
                          tree4_c = 3'd0;
                        end
                      end
                    end else begin
                      if (f_d2 <= 40) begin
                        if (f_d0 <= 149) begin
                          tree4_c = 3'd0;
                        end else begin
                          tree4_c = 3'd0;
                        end
                      end else begin
                        if (f_d3 <= 237) begin
                          tree4_c = 3'd0;
                        end else begin
                          tree4_c = 3'd0;
                        end
                      end
                    end
                  end
                end
              end else begin
                tree4_c = 3'd2;
              end
            end else begin
              if (f_d1 <= 41) begin
                if (f_d1 <= 40) begin
                  tree4_c = 3'd2;
                end else begin
                  if (f_d2 <= 58) begin
                    tree4_c = 3'd4;
                  end else begin
                    tree4_c = 3'd2;
                  end
                end
              end else begin
                if (f_d0 <= 244) begin
                  if (f_can_id <= 1087) begin
                    if (f_can_id <= 303) begin
                      tree4_c = 3'd2;
                    end else begin
                      if (f_d1 <= 144) begin
                        if (f_d1 <= 68) begin
                          tree4_c = 3'd2;
                        end else begin
                          tree4_c = 3'd0;
                        end
                      end else begin
                        tree4_c = 3'd2;
                      end
                    end
                  end else begin
                    tree4_c = 3'd2;
                  end
                end else begin
                  if (f_d2 <= 8) begin
                    if (f_d2 <= 0) begin
                      tree4_c = 3'd0;
                    end else begin
                      if (f_d1 <= 166) begin
                        tree4_c = 3'd0;
                      end else begin
                        tree4_c = 3'd2;
                      end
                    end
                  end else begin
                    tree4_c = 3'd2;
                  end
                end
              end
            end
          end
        end
    end
    always @(posedge clk) tree4_r <= tree4_c;

    // Stage 3: count votes.
    reg v3;
    always @(posedge clk) v3 <= rst ? 1'b0 : v2;
    reg [2:0] votes0;
    always @(posedge clk) votes0 <= (tree0_r == 3'd0) + (tree1_r == 3'd0) + (tree2_r == 3'd0) + (tree3_r == 3'd0) + (tree4_r == 3'd0);
    reg [2:0] votes1;
    always @(posedge clk) votes1 <= (tree0_r == 3'd1) + (tree1_r == 3'd1) + (tree2_r == 3'd1) + (tree3_r == 3'd1) + (tree4_r == 3'd1);
    reg [2:0] votes2;
    always @(posedge clk) votes2 <= (tree0_r == 3'd2) + (tree1_r == 3'd2) + (tree2_r == 3'd2) + (tree3_r == 3'd2) + (tree4_r == 3'd2);
    reg [2:0] votes3;
    always @(posedge clk) votes3 <= (tree0_r == 3'd3) + (tree1_r == 3'd3) + (tree2_r == 3'd3) + (tree3_r == 3'd3) + (tree4_r == 3'd3);
    reg [2:0] votes4;
    always @(posedge clk) votes4 <= (tree0_r == 3'd4) + (tree1_r == 3'd4) + (tree2_r == 3'd4) + (tree3_r == 3'd4) + (tree4_r == 3'd4);

    // Stage 4: most votes wins, strict > keeps ties on the lowest index.
    reg [2:0] best_c;
    reg [2:0] best_v;
    always @(*) begin
        best_c = 3'd0;
        best_v = votes0;
        if (votes1 > best_v) begin best_c = 3'd1; best_v = votes1; end
        if (votes2 > best_v) begin best_c = 3'd2; best_v = votes2; end
        if (votes3 > best_v) begin best_c = 3'd3; best_v = votes3; end
        if (votes4 > best_v) begin best_c = 3'd4; best_v = votes4; end
    end
    always @(posedge clk) begin
        out_valid <= rst ? 1'b0 : v3;
        class_out <= best_c;
    end
